package main

import "fmt"

func main() {
}

calls := 0
square := func(n int) int {
    calls++
    return n * n
}

cache := make(map[int]int)
get := func(n int) int {
    if hit, ok := cache[n]; ok {
        return hit
    }
    result := square(n)
    cache[n] = result
    return result
}

func fib(n int, memo map[int]int) int {
    if n < 2 {
        return n
    }
}

if cached, ok := memo[n]; ok {
    return cached
}
memo[n] = fib(n-1, memo) + fib(n-2, memo)
return memo[n]

func main() {
    memo := make(map[int]int)
    fmt.Println(fib(30, memo))
    fmt.Println(len(memo))
}

